"""Safe: amount computed server-side, not from client body."""
import razorpay
from flask import Flask, request, jsonify

app = Flask(__name__)
client = razorpay.Client(auth=("rzp_test_key", "secret"))


@app.route("/create-order", methods=["POST"])
def create_order():
    cart_id = request.json["cart_id"]
    # Safe: amount fetched from DB, not from client
    cart = Cart.get(cart_id)
    amount_paise = cart.total_paise  # server-computed, integer
    order = client.order.create({
        "amount": amount_paise,
        "currency": "INR",
        "receipt": cart_id,
    })
    return jsonify(order)


class Cart:
    @staticmethod
    def get(cart_id: str) -> "Cart":
        return Cart()

    @property
    def total_paise(self) -> int:
        return 150000  # stub: ₹1500

SAFE WEBHOOK_INTEGRITY example (correct handling):
"""
Safe: signature verification and dedup done in shared middleware (hard negative).
A static rule that only looks at this handler will miss the middleware guards.
"""
from flask import Flask, request, jsonify
from myapp.middleware import require_razorpay_signature, idempotent_event

app = Flask(__name__)


@app.route("/webhook", methods=["POST"])
@require_razorpay_signature  # middleware verifies X-Razorpay-Signature
@idempotent_event             # middleware deduplicates by X-Razorpay-Event-Id
def webhook():
    payload = request.json
    if payload.get("event") == "payment.captured":
        payment = payload["payload"]["payment"]["entity"]
        fulfill_order(payment["id"], payment["amount"])
    return jsonify({"status": "ok"}), 200


def fulfill_order(payment_id: str, amount: int):
    print(f"Fulfilling {payment_id}")

SAFE WEBHOOK_INTEGRITY example (correct handling):
"""Safe: webhook with full signature verification and event-id dedup."""
import razorpay
from flask import Flask, request, jsonify, abort

app = Flask(__name__)
client = razorpay.Client(auth=("rzp_test_key", "secret"))
WEBHOOK_SECRET = "webhook_secret_here"


@app.route("/webhook/razorpay", methods=["POST"])
def razorpay_webhook():
    raw_body = request.get_data(as_text=False)
    signature = request.headers.get("X-Razorpay-Signature", "")
    event_id = request.headers.get("X-Razorpay-Event-Id", "")

    # Safe: signature verified over raw bytes
    try:
        client.utility.verify_webhook_signature(raw_body.decode(), signature, WEBHOOK_SECRET)
    except Exception:
        abort(400, "Invalid signature")

    # Safe: event-id dedup check
    if ProcessedEvent.exists(event_id):
        return jsonify({"status": "already_processed"}), 200

    payload = request.json
    event = payload.get("event")
    if event == "payment.captured":
        payment = payload["payload"]["payment"]["entity"]
        ProcessedEvent.create(event_id)
        fulfill_order(payment["id"], payment["amount"])

    return jsonify({"status": "ok"}), 200


def fulfill_order(payment_id: str, amount: int):
    print(f"Fulfilling {payment_id}")


class ProcessedEvent:
    @staticmethod
    def exists(event_id: str) -> bool:
        return False  # stub

    @staticmethod
    def create(event_id: str) -> None:
        pass  # stub

