"""AC-R3 vulnerable: client-supplied amount flows to order creation."""
import razorpay
from flask import Flask, request, jsonify

app = Flask(__name__)
client = razorpay.Client(auth=("rzp_test_key", "secret"))


@app.route("/create-order", methods=["POST"])
def create_order():
    # BUG: amount comes from client. Attacker sends amount=1 and pays ₹0.01.
    amount = request.json["amount"]
    order = client.order.create({
        "amount": amount,
        "currency": "INR",
    })
    return jsonify(order)

UNSAFE DUPLICATE_PAYMENT example:
"""DP-R2 vulnerable: retry loop wraps order creation without idempotency."""
import razorpay

client = razorpay.Client(auth=("rzp_test_key", "secret"))


def create_order_with_retry(amount_paise: int, receipt: str, max_attempts: int = 3):
    for attempt in range(max_attempts):
        try:
            order = client.order.create({
                "amount": amount_paise,
                "currency": "INR",
                "receipt": receipt,
            })
            return order
        except Exception:
            if attempt == max_attempts - 1:
                raise

